        System.out.println("Plugin count: " + registry.getPluginCount());

        Graph graph = GraphBuilder.undirected(3).addEdge(0, 1).addEdge(1, 2).build();
        GraphService service = new GraphService(graph);
        registry.executeAll(service);
    }

