        validator.validate().print();
    }

    private static void demonstrateErrorHandling() {
        try {
            Graph graph = new UndirectedGraph(3);
            graph.addEdge(0, 5);
        } catch (GraphException.InvalidVertexException e) {
            System.out.println("Caught expected error: " + e.getMessage());
        }
    }
}

